#!/usr/bin/env python3
"""Extract pinned upstream declarations; no hand-translated reference algorithm.

Run from the repository root. --check validates the committed generated file and
manifest against Git objects, without network access or rewriting files.
"""
import argparse
import hashlib
import json
from pathlib import Path
import re
import subprocess

REVISION = 'd977e7a5e24e5536db6ce8b8478743e0c4b11f77'
ROOT = Path(__file__).resolve().parents[2]
OUTPUT = ROOT / 'backend/internal/service/codex_gateway_borrow_ranxi_generated_test.go'
MANIFEST = ROOT / '.downstream/ranxi-borrow-reference.json'
FILES = {
    'backend/internal/service/openai_codex_turn_state.go': ['guardOpenAICodexTurnStateEcho'],
    'backend/internal/service/openai_codex_state_probe.go': [
        'runOpenAICodexStateProbe', 'ProbeOpenAICodexStateRoute', 'fail',
        'shotUsable', 'openAICodexStateVerdictReason',
        'fireOpenAICodexStateShotRequest', 'openAICodexStateRouteCookies',
        'openAICodexStateDetail', 'openAICodexStateStreamEvents',
        'openAICodexStateStreamModel', 'openAICodexStateStreamErrorPayload'],
    'backend/internal/service/openai_codex_probe_response.go': ['validateCodexProbeResponse'],
    'backend/internal/service/openai_codex_ws_anchor.go': ['replaceCodexWSAnchorCookie'],
    'backend/internal/service/openai_codex_ticket.go': ['jsonString', 'normalizeOpenAICodexTicketModel'],
    'backend/internal/repository/codex_gateway_pin.go': ['codexGatewayCookiePathMatches', 'codexGatewayRouteFromResponse'],
    'backend/internal/service/account_test_service.go': ['createOpenAITestPayload'],
    'backend/internal/service/pelican_test_service.go': ['createPelicanOpenAIPayload', 'promptOrDefault', 'normalizePelicanReasoningEffort'],
}

def read(path):
    return subprocess.check_output(['git', 'show', f'{REVISION}:{path}'], cwd=ROOT)

def extract(source, name):
    pattern = r'(?m)^func (?:\([^\n]*\) )?' + re.escape(name) + r'\([^\n]*'
    start = re.search(pattern, source)
    if not start:
        raise ValueError('missing declaration: ' + name)
    end = re.search(r'(?m)^}', source[start.start():])
    if not end:
        raise ValueError('unterminated declaration: ' + name)
    return source[start.start():start.start() + end.end()] + '\n'

def generate():
    manifest = {'repository': 'ranxi2001/sub2api', 'tag': 'v2.10.5', 'commit': REVISION,
                'adaptations': ['Test-only identifier prefix; original function bodies.',
                  'Host HTTPUpstream, TLS profile, context markers, turn-state extractor and error display helpers.',
                  'Route container retains only cookie/expires; unused Mihomo/proxy fields are omitted.',
                  'Source payload calls the original Pelican builder with Astra, OAuth, fixed prompt and medium effort.'], 'files': {}}
    parts = []
    names = set()
    for path, functions in FILES.items():
        raw = read(path)
        source = raw.decode('utf-8')
        fragments = [extract(source, name) for name in functions]
        names.update(functions)
        if path.endswith('openai_codex_state_probe.go'):
            type_names = ['OpenAICodexStateVerdict', 'OpenAICodexStateProbeResult', 'openAICodexStateShot', 'openAICodexStateProbeContextKey']
            for name in type_names:
                # Multi-line structs, unlike the string alias and empty key.
                start = source.index('type ' + name + ' ')
                line_end = source.index('\n', start)
                if source[start:line_end].endswith('{'):
                    end = re.search(r'(?m)^}', source[line_end:])
                    fragment = source[start:line_end+end.end()]+'\n'
                else:
                    fragment = source[start:line_end]+'\n'
                fragments.append(fragment)
                names.add(name)
            for block in re.findall(r'(?m)^const \([\s\S]*?^\)', source):
                fragments.append(block+'\n')
                names.update(re.findall(r'(?m)^\t([A-Za-z]\w*)', block))
        for name, fragment in zip(functions, fragments):
            manifest['files'].setdefault(path, {'sha256': hashlib.sha256(raw).hexdigest(), 'declarations': {}})['declarations'][name] = hashlib.sha256(fragment.encode()).hexdigest()
        parts.extend(fragments)
    names.add('codexGatewayRoute')
    combined = '\n'.join(parts)
    combined = re.sub(r'\b('+'|'.join(sorted(names, key=len, reverse=True))+r')\b', lambda m: 'ranxiRef'+m[0][0].upper()+m[0][1:], combined)
    header = '''// Code generated by .github/scripts/generate_ranxi_borrow_reference.py; DO NOT EDIT.
// ranxi2001/sub2api v2.10.5, LGPL-3.0, commit '''+REVISION+'''.
package service
import (
 "bufio"
 "bytes"
 "context"
 "encoding/json"
 "errors"
 "fmt"
 "io"
 "net/http"
 "strings"
 "time"
 "github.com/google/uuid"
 "github.com/gin-gonic/gin"
 "github.com/Wei-Shaw/sub2api/internal/pkg/openai"
 "github.com/Wei-Shaw/sub2api/internal/pkg/tlsfingerprint"
)
type ranxiRefCodexGatewayRoute struct { cookie http.Cookie; expires time.Time }
'''
    data = subprocess.run(['gofmt'], input=(header+combined).encode(), capture_output=True, check=True).stdout.replace(b'\r\n', b'\n')
    manifest['generated_sha256'] = hashlib.sha256(data).hexdigest()
    # Adjacent host-dependent policies are reviewed by source hash, not replaced
    # with a second hand-written implementation or claimed as executed functions.
    manifest['reviewed_host_policies'] = {p: hashlib.sha256(read(p)).hexdigest() for p in [
      'backend/internal/repository/astra_target_validation.go',
      'backend/internal/repository/astra_routing_upstream.go',
      'backend/internal/service/astra_automatic_setup.go',
      'backend/internal/service/openai_codex_fingerprint.go']}
    return data, (json.dumps(manifest, indent=2)+'\n').encode()

if __name__ == '__main__':
    parser = argparse.ArgumentParser(); parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    generated, manifest = generate()
    if args.check:
        assert OUTPUT.read_bytes().replace(b'\r\n', b'\n') == generated
        assert MANIFEST.read_bytes().replace(b'\r\n', b'\n') == manifest
    else:
        OUTPUT.write_bytes(generated); MANIFEST.write_bytes(manifest)
    print('Pinned ranxi reference '+('verified' if args.check else 'generated'))
